function setUp() public {
    vm.warp(block.timestamp + 200 weeks);

    userCreator = new UserFactory();

    /// Create Voters
    address[] memory users = userCreator.create(7);
    voter0 = users[0];
    voter1 = users[1];
    voter2 = users[2];
    voter3 = users[3];
    voter4 = users[4];
    voter5 = users[5];

    /// Deploy kernel
    kernel = new Kernel(); // this contract will be the executor

    /// Deploy modules
    INSTR = new OlympusInstructions(kernel);
    VOTES = new OlympusVotes(kernel);

    /// Deploy policies
    governance = new OlympusGovernance(kernel);
    newProposedPolicy = new OlympusGovernance(kernel);

    /// Install modules
    kernel.executeAction(Actions.InstallModule, address(INSTR));
    kernel.executeAction(Actions.InstallModule, address(VOTES));

    /// Approve policies
    kernel.executeAction(Actions.ActivatePolicy, address(governance));

    // Generate test fixture policy addresses with different authorizations
    godmode = VOTES.generateGodmodeFixture(type(OlympusVotes).name);
    kernel.executeAction(Actions.ActivatePolicy, godmode);

    // Change executor
    kernel.executeAction(Actions.ChangeExecutor, address(governance));

    // Mint tokens to users for testing
    vm.startPrank(godmode);
    VOTES.mintTo(voter1, 100);
    VOTES.mintTo(voter2, 200);
    VOTES.mintTo(voter3, 300);
    VOTES.mintTo(voter4, 400);
    VOTES.mintTo(voter5, 500);
    vm.stopPrank();

    // approve token governance for transfers
    vm.prank(voter1);
    VOTES.approve(address(governance), type(uint256).max);
    vm.prank(voter2);
    VOTES.approve(address(governance), type(uint256).max);
    vm.prank(voter3);
    VOTES.approve(address(governance), type(uint256).max);
    vm.prank(voter4);
    VOTES.approve(address(governance), type(uint256).max);
    vm.prank(voter5);
    VOTES.approve(address(governance), type(uint256).max);
}

function submitProposal(
    Instruction[] calldata instructions_,
    bytes32 title_,
    string memory proposalURI_
) external {
    if (VOTES.balanceOf(msg.sender) * 10000 < VOTES.totalSupply() * SUBMISSION_REQUIREMENT)
        revert NotEnoughVotesToPropose();

    uint256 proposalId = INSTR.store(instructions_);
    getProposalMetadata[proposalId] = ProposalMetadata(
        title_,
        msg.sender,
        block.timestamp,
        proposalURI_
    );

    emit ProposalSubmitted(proposalId);
}

function grantApproval(
    address for_,
    ERC20 token_,
    uint256 amount_
) external onlyRole("custodian") {
    TRSRY.setApprovalFor(for_, token_, amount_);
}

function setApprovalFor(
    address withdrawer_,
    ERC20 token_,
    uint256 amount_
) external permissioned {
    withdrawApproval[withdrawer_][token_] = amount_;

    emit ApprovedForWithdrawal(withdrawer_, token_, amount_);
}
